#!/usr/bin/env python3
"""Turn 35 Wave 99: THE 5x100 CLASSIC, THE PRIZE LADDER'S REAL TIME COST, AND A DISSENT.

Wave 99's centrepieces:

1. THE 5x100 CLASSIC - the endgame asset the corpus had not priced. A Prize Ladder Classic
   can be coached to **five stats at 100**, and the named best first pick is **Desailly**,
   because a 5x100 defender with full fitness and full tackling is worth more than any of the
   attacking Classics. That reframes the Prize Ladder from a card-collection system into the
   cheapest route to a genuinely maxed defender, and it settles the corpus's "which Classic
   first" question.

2. THE PRIZE LADDER'S REAL TIME COST, which the corpus's DP arithmetic was missing. A match
   plus its ads is **9-10 minutes**, and the extra-DP ads **stop appearing after a while** -
   so the 145,000-DP final reward is roughly 250 matches, or about 40 hours. Paired with the
   dissent that the Classics are not worth caring about, that is the honest price of the
   system, and it is why the corpus's tier-camping gem route outranks it.

3. THE 500-COIN CLASSIC UNLOCK, and the two routes that conflict with it. The wiki and two
   Q&A sources say a Classic can be bought outright for 500 coins or unlocked by completing
   the game; the DLS25/26 reality is the DP Prize Ladder. Both are recorded, because the
   500-coin route is the older model and a player may still find it.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w99')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_path" if False else "artifact_path":"artifact_path","volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_pl=new_ev("r/DreamLeagueSoccer 1rkjr4i 'New Prize Ladder is Here!' (4 Mar 2026 - the 5x100 Classic concept, Desailly as the best first pick, and the observation that none of the Classics are 86), r/DreamLeagueSoccer 1pbdd5o (1 Dec 2025 - the Midfield Classics named with ratings: Matthaus 1991 86, Valderrama 1993 83, Rivaldo 1999 86, Pires 2002 84), r/DreamLeagueSoccer 1j43cc9 'New prize ladder tips and calculations' (5 Mar 2025 - the 9-10 minute per-match time cost, the extra-DP ads stopping after a while, and the dissent that the Classics are not worth caring about), dream-league-soccer.fandom.com/wiki/Classic_Players and /wiki/Player (the 500-coin Classic unlock and the complete-the-game route, with a corrupted ratings list), supercheats.com two Q&A threads (2012 and 2021 - the same 500-coin route), the App Store GB listing (official - 'LIVE EVENT English League Classics'), dlskiturl.com (6 Sep 2026 - the English League Classics with named players, the DP milestones, and 'most players are recycled from older events'), sportsdunia.com (30 Dec 2025 - the four Midfield Classics named), the official DLS TikTok (the Classics carrying a year and a rating; Roy Keane's unrevealed, Irvin's at 85), r/DreamLeagueSoccer 1qpe0dp (28 Jan 2026 - a complete competitive settings profile), r/DreamLeagueSoccer 1bsom9v (31 Mar 2024 - the goal-to-goal camera limitation), r/DreamLeagueSoccer 197ay88 (15 Jan 2024 - the goal-to-goal direction problem), LevelWinner DLS2022 guide (22 Jun 2022 - goal-to-goal eliminates the sideline's geometric distortion; use 100% distance), mokoweb.com (27 Sep 2026 - the same 100% distance rule), sportsdunia.com best-settings table (3 Mar 2026 - a FIFTH sportsdunia table)",
    "THE 5x100 CLASSIC, THE PRIZE LADDER'S REAL TIME COST, AND A DISSENT. (1) THE 5x100 CLASSIC, the endgame asset the corpus had not priced: '**You could probably make Desailly a 5x 100 defender** which is cool' and 'If you already are stacked with great strikers, I'd say your main man will be **Desailly**, who honestly I'd be most happy to get first. I could actually see him being a pretty good defender with potentially **5x 1000 with full fitness and full tackling**.' So a Prize Ladder Classic can be coached to **five stats at 100**, and the named best first pick is a DEFENDER, not a striker. **That reframes the Prize Ladder from a card-collection system into the cheapest route to a genuinely maxed defender**, and it settles the corpus's which-Classic-first question. The same thread notes '**none of them are 86 so none of them are gonna knock your socks off**' - so the Classics are not rating plays, they are maxing plays. (2) THE PRIZE LADDER'S REAL TIME COST, which the corpus's DP arithmetic was missing: 'avg time for 1 match is 8 mins... you also have to watch ads in between two halves... you dont get extra dp ads for every match. **they stop showing after a while**... adding all that makes it around **9-10 mins**.' So the 145,000-DP final reward is roughly 250 matches at 9-10 minutes - about 40 hours of play - and the DP-ad boost decays. (3) THE DISSENT: 'To get to lower tiers you'll have to spend time getting relegated, considering that you can't just enter a match and concede. **The real tip is: just don't care about classic players.** Play some matches for fun, just like you all used to do before prize ladder was a thing' and '**tier camping is bad. makes it unenjoyable for new players.**' A genuine argument that the whole system is not worth optimising for, which should sit beside the corpus's DP arithmetic rather than replace it. (4) THE 500-COIN CLASSIC UNLOCK, and the two routes that conflict with it: the wiki and two Q&A threads (2012 and 2021) say 'Classic Players can be unlocked with a **500 coin purchase or by completing the game** (beating your own team after First Touch United)... They rate from 85 up to 97', while the DLS25/26 reality is the DP Prize Ladder. **Both are recorded because the 500-coin route is the older model and a player may still find it in Transfers** - but the corpus's current answer is the Prize Ladder. (5) THE CURRENT PRIZE LADDER IS THE ENGLISH LEAGUE CLASSICS, confirmed by the official App Store listing ('LIVE EVENT English League Classics - Relive the glory days'), with **Berbatov CF, Essien DM, Andy Cole CF and Petit DM** at 62.5K / 115K / 175K / 250K DP, and the note that '**most players are recycled from older events**'. The PREVIOUS cycle was the Midfield Classics: **Matthaus 1991 (86) - Valderrama 1993 (83) - Rivaldo 1999 (86) - Pires 2002 (84)**, with one player reporting 'my Matthaus is kinda useless now' after the rotation. (6) THE CLASSICS CARRY A YEAR AND A RATING, per the official TikTok: Roy Keane's rating and year unrevealed, Irvin's at 85 - so each Classic is a specific season's version of the player, not a generic legend. (7) A COMPLETE COMPETITIVE SETTINGS PROFILE, DLS26-dated: '**Sideline camera, 30% zoom, game directional arrows OFF, radar map ON, names ON, scoreboard ON, kick assist OFF, cross assist OFF, pass assist OFF, basically all assist OFF. auto switch HIGH**.' That corroborates the corpus's Sideline-at-30% preference and adds the full assist list. (8) THE GOAL-TO-GOAL LIMITATION: 'Saving a c spam outside penalty box or anywhere within 30 yards from your own goal, **camera follow your CB with ball and the max view you're getting is the midline of midfield**' - so the vertical camera caps your defensive view at the halfway line. (9) THE GOAL-TO-GOAL DIRECTION PROBLEM: 'I like it when the direction of attacking is ahead... **But when the camera changes to attacking backward, I find the angle very awkward. I can barely see the attackers up front, especially trying to make a long pass from my goalie.**' So the camera flips with the attack direction, and the backward phase is the weak one. (10) THE 100% DISTANCE RULE, from two independent sources: 'it will be best to use the camera view that gives the best perspective: **goal to goal view. Using goal to goal eliminates the geometric distortion the sideline view has**... For maximum visibility, also choose the **100% view** for a wider field of vision' and 'it is best to configure it so that it is always **100% away from the lawn**.' (11) A FIFTH SPORTSDUNIA TABLE - the best-settings list - recorded so the rejection count is accurate, while noting its display-settings inventory (Player Names Above Head, Radar On, Opponent Player Names On, Direction Marker On, Ball Colour Automatic, Bounce Marker Off, Score Display On, Hide Multiplayer Opponent Data On, Colour Blind Mode Off) happens to be a usable checklist.",
    "THE 5x100 CLASSIC: a Prize Ladder Classic can be coached to FIVE STATS AT 100, and the named best first pick is DESAILLY - a defender, not a striker - because 5x100 fitness and tackling is worth more than any attacking Classic. So the Prize Ladder is not a rating play (none of the Classics are 86); it is the cheapest route to a genuinely maxed defender. THE PRIZE LADDER'S REAL TIME COST: 9-10 minutes per match with ads, and the extra-DP ads stop after a while - so 145,000 DP is roughly 250 matches, about 40 hours. Plus a genuine dissent that the Classics are not worth caring about. THE 500-COIN CLASSIC UNLOCK (the older model) recorded alongside the current DP route. THE CURRENT LADDER IS THE ENGLISH LEAGUE CLASSICS (Berbatov, Essien, Andy Cole, Petit), the previous one the Midfield Classics (Matthaus 86, Valderrama 83, Rivaldo 86, Pires 84), and each Classic carries a year. A COMPLETE COMPETITIVE SETTINGS PROFILE. THE GOAL-TO-GOAL LIMITATION AND DIRECTION PROBLEM. THE 100% DISTANCE RULE.",
    "THE 5x100 CLASSIC, THE PRIZE LADDER'S REAL TIME COST, AND A DISSENT",
    quality="community")

add_claim("THE 5x100 CLASSIC, the endgame asset the corpus had not priced: '**You could probably make Desailly a 5x 100 defender** which is cool' and 'If you already are stacked with great strikers, I'd say your main man will be **Desailly**, who honestly I'd be most happy to get first. I could actually see him being a pretty good defender with potentially **5x 1000 with full fitness and full tackling**.' **So a Prize Ladder Classic can be coached to five stats at 100, and the named best first pick is a DEFENDER, not a striker.**", 3, "prizeladder/5x100-classic-desailly-first", [e_pl], notes="Reframes the Prize Ladder as the cheapest route to a maxed defender")
add_claim("THE CLASSICS ARE NOT RATING PLAYS: '**none of them are 86 so none of them are gonna knock your socks off or revolutionise the game, but they're nice enough**' - so the value of a Prize Ladder Classic is in what it can be coached TO, not what it is. That is the same conclusion as the corpus's coaching economy, arriving from the acquisition side.", 3, "prizeladder/classics-are-not-rating-plays", [e_pl])
add_claim("THE PRIZE LADDER'S REAL TIME COST, which the corpus's DP arithmetic was missing: 'avg time for 1 match is 8 mins... you also have to watch ads in between two halves... **you dont get extra dp ads for every match. they stop showing after a while**... adding all that makes it around **9-10 mins**.' **So the 145,000-DP final reward is roughly 250 matches at 9-10 minutes - about 40 hours of play** - and the DP-ad boost decays, so the later tiers are slower than the early ones.", 3, "prizeladder/real-time-cost-9-10-minutes", [e_pl], notes="The honest price of the system; 40 hours against ~35-43 gems/hour from camping")
add_claim("A GENUINE DISSENT ON THE WHOLE SYSTEM: 'To get to lower tiers you'll have to spend time getting relegated, considering that you can't just enter a match and concede. **The real tip is: just don't care about classic players.** Play some matches for fun, just like you all used to do before prize ladder was a thing' and '**tier camping is bad. makes it unenjoyable for new players.**' Recorded beside the corpus's DP arithmetic rather than replacing it - the system can be optimised, and it can also simply be ignored.", 4, "prizeladder/dont-care-about-classics-dissent", [e_pl])
add_claim("THE 500-COIN CLASSIC UNLOCK, and the two routes that conflict with it: the wiki and two Q&A threads (2012 and 2021) say 'Classic Players can be unlocked with a **500 coin purchase or by completing the game** (beating your own team after First Touch United)... **They rate from 85 up to 97**', while the DLS25/26 reality is the DP Prize Ladder. **Both recorded because the 500-coin route is the older model and a player may still find it in Transfers** - but the corpus's current answer is the Prize Ladder.", 3, "prizeladder/500-coin-classic-unlock-legacy-route", [e_pl], notes="A legacy route recorded beside the current one, with the conflict stated")
add_claim("THE CURRENT PRIZE LADDER IS THE ENGLISH LEAGUE CLASSICS, confirmed by the official App Store listing ('LIVE EVENT English League Classics - Relive the glory days'): **Berbatov CF · Essien DM · Andy Cole CF · Petit DM** at 62.5K / 115K / 175K / 250K DP - with the note that '**most players are recycled from older events**'. So the ladder rotates and a player can appear twice.", 3, "prizeladder/english-league-classics-current", [e_pl], notes="Official store confirmation of the corpus's CLAIM-064")
add_claim("THE PREVIOUS CYCLE WAS THE MIDFIELD CLASSICS: **Matthaus 1991 (86) · Valderrama 1993 (83) · Rivaldo 1999 (86) · Pires 2002 (84)** - with one player reporting '**my Matthaus is kinda useless now**' after the rotation. So a Classic's value is tied to the cycle it belongs to, and the ladder's rotation retires cards.", 3, "prizeladder/midfield-classics-previous-cycle", [e_pl])
add_claim("EACH CLASSIC CARRIES A YEAR AND A RATING, per the official DLS TikTok: Roy Keane's rating and year are unrevealed, Irvin's is 85 - so a Classic is a **specific season's version** of the player, not a generic legend. That is why two Matthaus cards can differ and why the ladder's naming includes a year.", 3, "cards/classics-carry-a-year-and-rating", [e_pl])
add_claim("A COMPLETE COMPETITIVE SETTINGS PROFILE, DLS26-dated (January 2026): '**Sideline camera, 30% zoom, game directional arrows OFF, radar map ON, names ON, scoreboard ON, kick assist OFF, cross assist OFF, pass assist OFF, basically all assist OFF. auto switch HIGH.**' That corroborates the corpus's Sideline-at-30% preference and adds the full assist and display list - and note the auto-switch-HIGH position sits against the corpus's manual-switching advice, which is the same split verdict recorded at wave 93.", 3, "settings/complete-competitive-profile", [e_pl])
add_claim("THE GOAL-TO-GOAL LIMITATION: 'Saving a c spam outside penalty box or anywhere within 30 yards from your own goal, **camera follow your CB with ball and the max view you're getting is the midline of midfield.**' **So the vertical camera caps your defensive view at the halfway line** - which is exactly where a C-spam target stands, and a reason the Sideline camera is the competitive favourite.", 3, "settings/goal-to-goal-defensive-view-limit", [e_pl])
add_claim("THE GOAL-TO-GOAL DIRECTION PROBLEM: 'I like it when the direction of attacking is ahead. The angle makes it very easy to build up attack, pass, and shoot. Defending is a harder but still acceptable. **But when the camera changes to attacking backward, I find the angle very awkward. I can barely see the attackers up front, especially trying to make a long pass from my goalie.**' So the camera flips with the attack direction, and the backward phase is the weak one - a specific cost of the vertical view.", 3, "settings/goal-to-goal-direction-problem", [e_pl])
add_claim("THE 100% DISTANCE RULE, from two independent sources: 'since precision passing and shooting are prerequisites for success... it will be best to use the camera view that gives the best perspective: **goal to goal view. Using goal to goal eliminates the geometric distortion the sideline view has**... For maximum visibility, also choose the **100% view** for a wider field of vision' and 'it is best to configure it so that it is always **100% away from the lawn**.' So distance at maximum, whichever camera type you pick.", 3, "settings/100-percent-distance-rule", [e_pl])
add_claim("A FIFTH SPORTSDUNIA TABLE - the best-settings list - recorded so the rejection count is accurate, while noting that its display-settings inventory (**Player Names Above Head, Radar On, Opponent Player Names On, Direction Marker On, Ball Colour Automatic, Bounce Marker Off, Score Display On, Hide Multiplayer Opponent Data On, Colour Blind Mode Off**) happens to be a usable checklist even though the source is rejected for tables.", 4, "errata/sportsdunia-fifth-table", [e_pl], notes="Fifth sportsdunia rejection; the display checklist is noted but not adopted as evidence")

for p in ['EV-512_5x100_classic.html','EV-512b_prize_ladder_cost_and_camera.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
